contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _recipient) public payable {
        require(_recipient != address(0), "recipient must be nonzero");
        require(_recipient != address(c), "recipient must not be c");

        uint256 balanceBefore = address(c).balance;
        uint256 recipBalanceBefore = _recipient.balance;

        bool reverted;
        c.withdrawAll(_recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && address(c).balance == 0 && _recipient.balance == recipBalanceBefore + balanceBefore);
    }

    receive() external payable {}
}

